 per_case.append({'case':name,'input_tokens':len(case['input_ids']),'output_tokens_per_pass':200,'candidate_repeat_ids_equal':True,'target_repeat_ids_equal':True,'candidate_finish_reason':'length=200','target_finish_reason':'length=200','requests_match_target':True,'candidate_matches_target':False,'first_divergence_zero_based':first,'target_id_at_divergence':ti[first],'candidate_id_at_divergence':ai[first],'differing_id_positions_total':sum(x!=y for x,y in zip(ai,ti)),'target_selected_token_logprob_at_divergence':meta_t['output_token_logprobs'][first][0],'candidate_selected_token_logprob_at_divergence':meta_a['output_token_logprobs'][first][0],'logprob_scope':'Selected token only; alternative/top-two logits and margin were not collected.','candidate_elapsed_s':[a['elapsed_s'],b['elapsed_s']],'target_elapsed_s':[ta['elapsed_s'],tb['elapsed_s']],'candidate_queue_time_s':[meta_a.get('queue_time'),meta_b.get('queue_time')],'spec_verify_ct':spec['spec_verify_ct'],'spec_num_correct_drafts':spec['spec_num_correct_drafts'],'spec_num_proposed_drafts':spec['spec_num_proposed_drafts'],'spec_accept_rate':spec['spec_accept_rate'],'spec_accept_percent':round(100*spec['spec_accept_rate'],3),'spec_accept_length':spec['spec_accept_length'],'counters_repeat_equal':True})
