def server_args(job,role):
 text=(BASE/'runs'/job/f'{role}.log').read_text(errors='replace');line=next(x.split('server_args=',1)[1] for x in text.splitlines() if 'server_args=ServerArgs(' in x);call=ast.parse(line,mode='eval').body
 return {kw.arg:ast.literal_eval(kw.value) if _literal(kw.value) else ast.unparse(kw.value) for kw in call.keywords if kw.arg}
def _literal(node):
 try:ast.literal_eval(node);return True
 except:return False
def graph_summary(v):
 call=ast.parse(v,mode='eval').body;out={}
 for p in call.keywords:
  if p.arg in ('decode','prefill'):
   vals={q.arg:(ast.literal_eval(q.value) if _literal(q.value) else ast.unparse(q.value)) for q in p.value.keywords if q.arg}
   out[p.arg]={'backend':vals.get('backend'),'max_bs':vals.get('max_bs'),'bs':vals.get('bs')}
 return out
