 ranges={}
 for k in ('memory.used','utilization.gpu','power.draw','temperature.gpu'):
  vals=[float(x[k]) for x in g if x.get(k) not in (None,'N/A','[N/A]')];ranges[k]={'min':min(vals),'max':max(vals)} if vals else 'not_collected'
 mem=[x['node_memory']['MemAvailable_KiB'] for x in ss if x.get('node_memory')]
 telemetry[role]={'sample_count':len(ss),'unique_sampled_gpu_count':len({x.get('uuid') for x in g}),'expected_gpu_count':n,'gpu_ranges':ranges,'host_memavailable_gib_range':[round(min(mem)/1048576,2),round(max(mem)/1048576,2)] if mem else 'not_collected','gpu_status_counts':dict(collections.Counter(str(x.get('gpu_status','missing')) for x in ss)),'server_metrics_status_counts':dict(collections.Counter(str(x.get('server_metrics_status','missing')) for x in ss)),'scope':'Bounded startup and sequential N=1 candidate samples; no scored interval and no causal inference.'}
