review={'job':'25862','reviewed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'state':'H200_EAGLE3_EXACT_TARGET_REFERENCE_GATE_FAILED_RUNTIME_AND_SEMANTIC_READINESS_PASSED','experiment_id':ctx['experiment_id'],'terminal_receipt':{'state':status[0]['State'],'exit_code':status[0]['ExitCode'],'elapsed':status[0]['Elapsed'],'start':status[0]['Start'],'end':status[0]['End'],'source':'independent Slurm sacct -X; raw receipt retained in accounting.psv'},'seal_sha256':sealsha,'submitted_payload_files_verified':len(manifest),'head_checker':'Fails at result.passed assertion because the strict exact-ID comparison set passed=false. This is localized to acceptance; runtime readiness and source/geometry/semantic checks independently pass.','accepted_reference':{'job':'25855','path':str(TARGET/'target-reference.json'),'sha256':bind['target_reference_sha256'],'review_json_sha256':bind['target_review_json_sha256'],'review_seal_sha256':bind['target_review_seal_sha256'],'accepted_review_state':accepted['state']},'runtime_readiness':{'state':'PASS','all_ranks_deterministic':True,'dtype':'bfloat16','sampling':'pytorch','global_attention':'fa3','prefill_cuda_graph':'disabled','decode_cuda_graph':'full batch sizes 1..64','role_checks':{'prefill-0':'4/4 TP ranks; 8 BF16 KV allocation records (2/rank); 4 NIXL ranks','prefill-1':'4/4 TP ranks; 8 BF16 KV allocation records (2/rank); 4 NIXL ranks','decode-0':'8/8 TP ranks; 16 BF16 KV allocation records (2/rank); 8 NIXL ranks'},'EAGLE3':{'steps':2,'topk':1,'draft_tokens':3,'draft_attention_backend':'flashinfer'}},'geometry':{'state':'PASS','regions_per_prefill_rank':190,'rank_count':16,'receipt_count':32,'receipt_bytes':geometry['receipt_bytes'],'decode_kv_heads':'not collected','layer_ids':'empty/not proven; not inferred'},'semantic_pd_receipts':{'state':'PASS','receipt_count':2,'inventory_sha256':ctx['endpoint_inventory_sha256'],'run_token':hashlib.sha256(ctx['experiment_id'].encode()).hexdigest()[:32]},'exact_output_gate':{'state':'FAIL','candidate_repeat_stability':True,'target_repeat_stability':True,'request_equal_to_target':True,'cases':per_case,'passes':2,'output_ids_total_both_passes':1600,'ids_each_pass':800,'all_four_cases_differ_from_accepted_target':True,'finish_reason_all_passes':'length=200','native_counters_present_and_repeat_equal':True,'official_quality_verdict':False},'resolved_runtime_comparison':resolved,'environment_comparison':{'SGLANG_ENABLE_TORCH_INFERENCE_MODE':'Neither submitted worker exports it; effective worker process environment was not retained, so this is not a known run-to-run confound.','prefill_and_decode_backends':'Resolved global FA3, default prefill backend, decode FlashInfer, and NIXL P/D modes match between target and candidate.','active_graph_coverage':'Prefill graph disabled and decode graph full 1..64 in both. Different batch-size entries occur only in disabled prefill-worker decode graph config.','other_observed_differences':'EAGLE3 treatment fields; auto-generated random_seed values; resolved prefill max_running_requests=None for target versus 48 for S49. The diagnostic runs one request at a time, so the 48 cap was not approached. Different per-worker random seeds are present under greedy sampling; no causal link is established.'},'phase_times':phases,'request_diagnostics':{'concurrency':1,'requests_sequential':True,'elapsed_s_by_case':{x['case']:{'eagle_a':x['candidate_elapsed_s'][0],'eagle_b':x['candidate_elapsed_s'][1],'target_a':x['target_elapsed_s'][0],'target_b':x['target_elapsed_s'][1]} for x in per_case},'queue_time_s_by_candidate_case':{x['case']:x['candidate_queue_time_s'] for x in per_case},'scope':'Eight sequential exactness diagnostic requests; no benchmark score, throughput claim, or meaningful tail percentile.'},'telemetry':telemetry,'cost':{'allocated_gpus':16,'elapsed_s':557,'allocated_gpu_minutes':round(16*557/60,2),'interpretation':'Scheduler allocation arithmetic only; no dollar estimate.'},'logs_and_errors':{'NIXL_ERR':'not found','CUDA_OOM':'not found','terminal_failure':'Head exact-reference assertion; runtime shutdown subsequently records Slurm step cancellations after signal-kill teardown. No startup or semantic receipt failure.'},'source_proof':source,'source_based_numerical_hypothesis':'A plausible bounded cause is shape-dependent numerical variation: pinned SGLang source shows EAGLE target verification builds one batched forward from drafted token rows, then greedy-argmaxes every verification row; ordinary target decode uses a per-position sampler path. All repeated candidate outputs are stable, but the paths first diverge at the four recorded positions. The response API retained only selected-token log probabilities, not alternate logits or margins; the hypothesis is unproven. If separately authorized, a narrow diagnostic could capture top-two target logits for the same frozen prefix at just each first-divergence position in ordinary single-token decode and the corresponding EAGLE target-verify row. No retry or GPU action was taken.','limits':['No official model quality or accuracy conclusion follows from this four-case deterministic exact-reference diagnostic.','No score or matched performance measurement was collected.','Alternative logits/margins were not collected; selected-token log probabilities do not establish a near tie.','No per-process GPU kernel-time profile or scored interval exists.','System CPU/network counters are sampled at host level and are not attributable to this job.']}
